126			"null field":          `{"account":null,"operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
127			"wrong type":          `{"account":1,"operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
128			"blank account":       `{"account":"   ","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
129			"forbidden hash":      `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","hash":"x"}`,
